void print(char c[], int n)
{
    int i=0;
    int effective_n;
    if(n>=26)
        effective_n=n%26;
    else
        effective_n=n;

    while(c[i]!=0)
    {
        if((c[i]+effective_n)>'z')
            printf("%c",c[i]+effective_n-'z');
        else
            printf("%c",c[i]+effective_n);
        i++;
    }
}

