#include <stdio.h>

int read(char a[]){
    int i,count=0;
    char c;
    c=getchar();
    for(i=0;c!='\n';i++){
        a[i]=c;
        count=count+1;
        c=getchar();
    }

    a[count]='\0';
    return count;
}

void shift(char a[],int n,int count){
    int i,l,p;
    char c;
    l=n%26;
    for(i=0;i<count;i++){
        c=a[i]+l;
        if((c<='a')||(c>='z')){
            p=a[i]+l-'z';
            c='a'+p-1;
        }
        printf("%c",c);
    }


}

int main() {
	char a[100];
	int n,b;
	b = read(a);
	scanf("\n%d",&n);
	shift(a,n,b);

	return 0;
}

